// JSON imports widen string literals, so fixtures are read through this typed helper.
// The files are generated by `uv run python -m poker_trainer.api.dev_fixtures` (see the backend).
import type {
  AttemptResult,
  Explanation,
  HandAnalysis,
  HistoryPage,
  PlayHandSummary,
  PlaySessionSummary,
  PlaySessionView,
  PuzzleView,
  SettingsView,
  StatsView,
} from '../api/types'

const files = import.meta.glob<unknown>('./fixtures/*.json', { eager: true, import: 'default' })

export type FixtureName =
  | `puzzle_${string}`
  | `attempt_${string}`
  | 'settings'
  | 'explanation_llm'
  | 'stats'
  | 'stats_empty'
  | 'history_page'
  | `play_${string}`

/** Loads `src/test/fixtures/<name>.json`, trusting the caller's type (the files come from the API). */
export function fixture<T = PuzzleView>(name: FixtureName): T {
  const data = files[`./fixtures/${name}.json`]
  if (data === undefined) throw new Error(`no fixture named ${name}`)
  return data as T
}

export function fixtureNames(): FixtureName[] {
  return Object.keys(files)
    .map((path) => path.replace(/^\.\/fixtures\//, '').replace(/\.json$/, '') as FixtureName)
    .sort()
}

export const puzzleFixture = (name: string): PuzzleView => fixture<PuzzleView>(`puzzle_${name}`)
export const attemptFixture = (name: string): AttemptResult =>
  fixture<AttemptResult>(`attempt_${name}`)
export const settingsFixture = (): SettingsView => fixture<SettingsView>('settings')
export const statsFixture = (): StatsView => fixture<StatsView>('stats')
export const statsEmptyFixture = (): StatsView => fixture<StatsView>('stats_empty')
export const historyFixture = (): HistoryPage => fixture<HistoryPage>('history_page')
export const explanationLlmFixture = (): Explanation => fixture<Explanation>('explanation_llm')

export const playSessionFixture = (name: 'hero_to_act' | 'hand_over_fold' | 'hand_over_showdown') =>
  fixture<PlaySessionView>(`play_session_${name}`)
export const playHandAnalysisFixture = (): HandAnalysis =>
  fixture<HandAnalysis>('play_hand_analysis')
export const playSessionsFixture = (): PlaySessionSummary[] =>
  fixture<PlaySessionSummary[]>('play_sessions')
export const playHandsFixture = (): PlayHandSummary[] => fixture<PlayHandSummary[]>('play_hands')
